r"""修复 source 页里「双反斜杠转义引号」导致的 frontmatter YAML 解析失败。

症状：长文本字段写成 "...\\"..."（反斜杠+引号），YAML 把 \\" 解析为字面反斜杠后
      遇到未转义的 " 提前结束标量 => 整个 frontmatter 解析失败 => 元数据在索引层静默丢失。

修法：把 \\" 规范为 \"（单反斜杠转义），即 YAML 双引号标量中合法的转义引号。

写法纪律（CLAUDE.md §五「写盘铁律」）：
  · 默认干跑，`--apply` 才写盘；
  · **写前用与被校验系统同一个解析器复核**（此处即 kb_lib.split_frontmatter）；
  · 闭合 `---` 后必须补换行，否则 frontmatter 整个解析不出来（曾一次写坏 124 页）。

用法:
    python tools/qc_fix_yaml.py              # 干跑
    python tools/qc_fix_yaml.py --apply      # 就地修复
    python tools/qc_fix_yaml.py --selftest   # 校验器自检
"""
import sys, os, re, glob, argparse, shutil, tempfile, contextlib


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, split_frontmatter  # noqa: E402

import yaml

BAD_ESC = '\\\\"'      # 双反斜杠 + 引号（坏形态）
GOOD_ESC = '\\"'       # 单反斜杠 + 引号（YAML 合法转义）


# ---------------------------------------------------------------- 写盘三件套
#
# 2026-10-10 补齐：本文件此前只有「写前同解析器复核」，缺**备份**与**写后复算**，
# 违反 CLAUDE.md §五「写盘铁律」第 3 条。这里补齐，并统一落 `.qc/backups/YYYYMMDD/`
# （与 kb_lint.py / qc_si_sweep.py 同一命名，便于人工在一个地方找回退点）。

import kb_lib as K          # 写盘三件套与自检守卫的唯一实现（本块只是薄委托）
K.console_encoding()


def backup_dir():
    """本次运行的备份目录 `<ROOT>/.qc/backups/YYYYMMDD/`。

    实现已收敛到 `kb_lib.backup_root()`（单一出口）——此前本块在 5 个 qc 工具里
    各有一份约 150 行的副本，与 `kb_lint`/`lit_finish` 的实现又各自不同。
    传 `root=ROOT` 是**自检隔离**所必需：selftest 把 ROOT 指向合成目录，
    备份必须跟着进合成目录。
    """
    return K.backup_root(root=ROOT)


def backup_files(paths):
    """写盘前按原字节备份，保留相对库根结构；**失败即抛错**（铁律 3）。

    见 `kb_lib.backup_file/backup_files`（保留目录结构是为了同名页不互相覆盖）。
    """
    return K.backup_files(paths, root=ROOT)


def write_keep_eol(path, text):
    """按原文件换行风格写回（实现见 `kb_lib.write_text_keep_eol`）。

    本库换行是 CRLF/LF 混合：直接以 `newline="\n"` 写回会把 CRLF 页面整篇翻成 LF，
    diff 里出现成百上千行纯换行噪声、真实改动被淹没。
    """
    return K.write_text_keep_eol(path, text)


def verify_written(paths):
    """写后复算（实现见 `kb_lib.verify_written`）：写 N 个就要能读回 N 个。

    不通过即打印原因并 `SystemExit(2)` —— 不信"写的时候没报错"：
    `qc_evidence_base.py` 曾因闭合 `---` 后漏换行一次性写坏 124 页。
    """
    return K.verify_written(paths, root=ROOT)


# ---------------------------------------------------------------- 自检守卫

def _guard_state(wiki_glob=False, extra_paths=()):
    """真实落点的 (mtime_ns, size) 快照（实现见 `kb_lib.guard_state`）。"""
    return K.guard_state(ROOT, wiki_glob=wiki_glob, extra_paths=extra_paths)


def _guard_diff(before, after):
    """两次快照的差异（实现见 `kb_lib.guard_diff`）。"""
    return K.guard_diff(before, after)





@contextlib.contextmanager
def temp_root():
    """把「库根」临时指向一个合成目录，**只在本进程内**改模块级变量。

    为什么要它：selftest 必须走真实的写盘路径（否则测的是另一个函数），
    但**绝对不能在真库上写**。做法是让 ROOT / 工作目录在 selftest 期间整体
    指向 tempfile 合成库——写盘路径一字不改地跑，落点全在临时目录里。
    退出时无论成败都恢复，避免合成路径泄漏到后续逻辑。
    """
    old_root, old_cwd = ROOT, os.getcwd()
    tmp = K.make_temp_dir(prefix="qc_fix_yaml_selftest_")
    try:
        globals()["ROOT"] = tmp
        os.chdir(tmp)
        yield tmp
    finally:
        os.chdir(old_cwd)
        globals()["ROOT"] = old_root
        shutil.rmtree(tmp, ignore_errors=True)


def split_fm(t):
    """返回 (frontmatter_text, body) 或 None。

    🔴 2026-10-10 改为**直接委托 `kb_lib.split_frontmatter`**：
    本函数原先自带一份 `t.find("\\n---", 3)` 的实现，与真解析器**不是同一个规则**
    （对 `---` 后的空白/行尾处理不同）。CLAUDE.md 铁律第 2 条要求"写前用与被校验
    系统同一个解析器复核"——留着第二份实现，就等于永远存在"校验通过、实际已坏"的口子。
    """
    if not t.startswith("---"):
        return None
    fm, body = split_frontmatter(t)
    if not fm.strip():
        return None
    return fm, body


def rebuild(fmb, body):
    r"""按**同一解析器**能读出的形态重建全文。

    ⚠️ 两个必须成立的换行条件（二者同源，都是「frontmatter 静默失效」成因）：
      1. **开围栏 `---` 后必须有换行**：写成 `"---" + fmb` 会产出
         `---summary: "..."`，`kb_lib.split_frontmatter` 要求 `---` 后跟 `\n`
         ⇒ frontmatter 整个解析不出来。**本文件的旧实现正是这样写的**
         （`"---" + new + "\n---" + body`），selftest 当场抓到。
      2. **闭合 `---` 后必须有换行**：CLAUDE.md 明载曾一次写坏 124 页。

    ⇒ 统一委托给 `kb_lib.join_frontmatter`，不再手写拼接。
    """
    from kb_lib import join_frontmatter
    return join_frontmatter(fmb, body)


def attempt_fix(fmb):
    """尝试把坏转义规范化为合法转义；返回新 frontmatter 或 None。"""
    new = fmb.replace(BAD_ESC, GOOD_ESC)
    try:
        yaml.safe_load(new)
    except Exception:
        return None
    # 复核：修完必须能被**同一个** kb_lib 解析器切出来（不是另写宽松正则）
    got, _ = split_frontmatter(rebuild(new, "x"))
    if not got.strip():
        return None
    return new


def scan():
    """返回 (fixed, still_bad) 两份路径清单。不写盘。"""
    fixed, still_bad = [], []
    for f in sorted(glob.glob("wiki/**/*.md", recursive=True)):
        if "/.index/" in f.replace(os.sep, "/"):
            continue
        t = read_text(f)
        sp = split_fm(t)
        if not sp:
            continue
        fmb, body = sp
        try:
            yaml.safe_load(fmb)
            continue  # 本来就 OK
        except Exception:
            pass
        if attempt_fix(fmb) is None:
            still_bad.append(f)
        else:
            fixed.append(f)
    return fixed, still_bad


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）+ 写盘路径隔离夹具。"""
    ok = True

    # 🔴 守卫：进入时对真实落点拍快照，退出前比对——证明自检没碰真实库
    guard = _guard_state(wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),))

    # 正例：双反斜杠转义引号 → 修后 safe_load 必须通过
    bad_fm = 'summary: "a ' + BAD_ESC + ' b"\n'
    try:
        yaml.safe_load(bad_fm)
        before = "OK"
    except Exception:
        before = "BAD"
    newfm = attempt_fix(bad_fm)
    after = "OK" if newfm is not None else "BAD"
    got = before == "BAD" and after == "OK"
    print(f"  [{'ok' if got else 'FAIL'}] 正例 坏 YAML 修好 "
          f"(修前 {before} / 修后 {after})")
    ok = ok and got

    # 🔴 回归夹具：闭合 --- 后必须解析得出来（曾一次写坏 124 页的形态）
    good_fm = 'summary: "正常的摘要"\n'
    probe = rebuild(good_fm, "# 标题\n正文\n")
    got_fm, got_body = split_frontmatter(probe)
    parsed = None
    if got_fm:
        try:
            parsed = yaml.safe_load(got_fm)
        except Exception:
            parsed = None
    good = (bool(got_fm) and isinstance(parsed, dict)
            and parsed.get("summary") == "正常的摘要"
            and got_body.lstrip().startswith("# 标题"))
    print(f"  [{'ok' if good else 'FAIL'}] 回归：重建后同一解析器可读出 frontmatter")
    ok = ok and good

    # 反例：本来就是好的 frontmatter **不得被改坏**
    clean_fm = 'summary: "无需修复"\n'
    got = attempt_fix(clean_fm)
    still_ok = got is not None and "无需修复" in got
    print(f"  [{'ok' if still_ok else 'FAIL'}] 反例 无坏转义者不被改坏")
    ok = ok and still_ok

    # 反例：**无法**靠替换修好的 YAML 必须返回 None（不得假装修好）
    unfixable = "tags: [a, b\n"
    got = attempt_fix(unfixable)
    print(f"  [{'ok' if got is None else 'FAIL'}] 反例 不可修复者返回 None")
    ok = ok and got is None

    # 反例：split_fm 对无 frontmatter 的文本返回 None
    got = split_fm("# 没有 frontmatter\n")
    print(f"  [{'ok' if got is None else 'FAIL'}] 反例 无 frontmatter -> None")
    ok = ok and got is None

    # ---- 夹具（只对合成库，绝不碰真库）：完整写盘路径 ----
    try:
        with temp_root() as tmp:
            wd = os.path.join(tmp, "wiki", "sources")
            os.makedirs(wd, exist_ok=True)
            p_ok = os.path.join(wd, "A-坏转义.md")
            p_clean = os.path.join(wd, "B-正常.md")
            p_nofm = os.path.join(wd, "C-无frontmatter.md")
            with open(p_ok, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\ncreated: 2026-01-01\nsummary: \"a %s b\"\n---\n\n# 标题\n正文\n"
                         % BAD_ESC)
            with open(p_clean, "w", encoding="utf-8", newline="\n") as fh:
                fh.write('---\nsummary: "本来就正常"\n---\n\n# 好页\n')
            with open(p_nofm, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("# 没有 frontmatter\n")

            # 夹具 1（正例）：合成库里能识别出坏页
            fixed, still = scan()
            c1 = (len(fixed) == 1 and fixed[0].endswith("A-坏转义.md") and still == [])
            print(f"  [{'ok' if c1 else 'FAIL'}] 夹具 正例 合成库识别坏页 -> "
                  f"可修复 {[os.path.basename(x) for x in fixed]} / 仍失败 {len(still)}")
            ok = ok and c1

            # 夹具 2（🔴 frontmatter 不丢）：走真实写盘路径，写前备份 + 写后复算
            paths = [p_ok, p_clean]
            saved = backup_files(paths)
            written = []
            for f in paths:
                t = read_text(f)
                sp = split_fm(t)
                if not sp:
                    continue
                fmb, body = sp
                new = attempt_fix(fmb)
                if new is None:
                    continue
                out = rebuild(new, body)
                chk, _ = split_frontmatter(out)
                if not chk.strip():
                    continue
                write_keep_eol(f, out)
                written.append(f)
            c2 = len(written) == 2 and len(saved) == 2
            fm_a, body_a = split_frontmatter(read_text(p_ok))
            import yaml as _y
            parsed_ok = None
            try:
                parsed_ok = _y.safe_load(fm_a)
            except Exception:
                parsed_ok = None
            c2 = c2 and isinstance(parsed_ok, dict) and body_a.lstrip().startswith("# 标题")
            print(f"  [{'ok' if c2 else 'FAIL'}] 🔴 夹具 frontmatter 不丢：写后仍被同一"
                  f"解析器读出（备份 {len(saved)} / 写 {len(written)}）")
            ok = ok and c2

            # 夹具 3：写后复算能抓出"写了但 frontmatter 读不出"的坏页（反例）
            p_broken = os.path.join(wd, "D-写坏了.md")
            with open(p_broken, "w", encoding="utf-8", newline="\n") as fh:
                fh.write("---\nsummary: x\n---# 标题\n")   # 闭合 --- 后缺换行（124 页事故形态）
            caught = False
            sys.stdout.flush()          # 让下面 stderr 的告警落在夹具判定之后，输出不串行
            try:
                verify_written([p_ok, p_broken])
            except SystemExit as e:
                caught = (e.code or 0) != 0
            print(f"  [{'ok' if caught else 'FAIL'}] 反例 写后复算抓出 frontmatter 丢失"
                  f"（并置非零退出）")
            ok = ok and caught
            # 正例：全部正常时复算必须通过
            passed = True
            try:
                verify_written([p_ok, p_clean])
            except SystemExit:
                passed = False
            print(f"  [{'ok' if passed else 'FAIL'}] 正例 写后复算：写 2 读回 2 通过")
            ok = ok and passed
    except Exception as e:                                        # noqa: BLE001
        print(f"  [FAIL] 夹具异常: {type(e).__name__}: {e}")
        ok = False

    # 正例：真实库扫描跑通（只读）
    fixed, still_bad = scan()
    print(f"  [info] 全库扫描 -> 可修复 {len(fixed)} | 仍失败 {len(still_bad)}")

    # 🔴 守卫：自检未改动仓库内任何落点
    diff = _guard_diff(guard, _guard_state(
        wiki_glob=True, extra_paths=(os.path.join(ROOT, ".qc"),)))
    print(f"  [{'ok' if not diff else 'FAIL'}] 🔴 守卫：自检未改动仓库内任何落点"
          f"（{len(diff)} 处变化）")
    if diff:
        for d in diff[:10]:
            print("       ", d)
    ok = ok and not diff

    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="修复双反斜杠转义引号导致的 YAML 解析失败")
    ap.add_argument("--apply", action="store_true", help="就地修复（默认干跑）")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    fixed, still_bad = scan()

    for f in fixed:
        print("  FIXED:", os.path.basename(f))
    for f in still_bad:
        print("  STILL-BAD:", os.path.basename(f))
    print("\n%s: 修复 %d ｜ 仍失败 %d" % ("APPLIED" if a.apply else "DRY-RUN",
                                          len(fixed), len(still_bad)))
    if not a.apply:
        if fixed:
            print("加 --apply 执行修复")
        return 0

    # —— 铁律 3：批量写盘前先备份、写后复算总量 ——
    saved = backup_files(fixed)
    if fixed and not saved:
        print("❌ 备份失败，拒绝写盘", file=sys.stderr)
        return 2
    print("备份 %d 个待改文件 -> %s" % (len(saved), backup_dir()))

    written = []
    for f in fixed:
        t = read_text(f)
        sp = split_fm(t)
        if not sp:
            print("  [skip] 复核失败（未写盘）:", os.path.basename(f))
            continue
        fmb, body = sp
        new = attempt_fix(fmb)
        if new is None:
            print("  [skip] 复核失败（未写盘）:", os.path.basename(f))
            continue
        out = rebuild(new, body)
        # 写前复核：必须仍能被同一解析器读出
        chk, _ = split_frontmatter(out)
        if not chk.strip():
            print("  [skip] 写前复核失败（未写盘）:", os.path.basename(f))
            continue
        write_keep_eol(f, out)
        written.append(f)
    print("已写盘 %d 页（写前均通过同一解析器复核）" % len(written))
    verify_written(written)
    return 0


if __name__ == "__main__":
    sys.exit(main())
